<?php
declare(strict_types=1);
function cat_new(array $a,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Создание брифа доступно в кабинете клиента.');return crm_idempotent('catalog:customer:'.$a['id'].':new',$d,function()use($a,$d){$policy=cat_consent($d);$live=cat_live(cc_id($d['service_version_id']??null));$v=$live['version'];$package=cat_package($v,cat_key($d['package_key']??null));$p=crm_insert('projects',['customer_id'=>(int)$a['customer_id'],'title'=>mb_substr($v['data']['name'].' — '.$package['name'],0,190),'description'=>'Черновик брифа. Заказ ещё не создан.','status'=>'planned'],$a)['record'];
 crm_query('INSERT INTO nd_catalog_requests(customer_id,account_id,service_version_id,package_key,project_id,answers_json,file_ids_json,consent_at,policy_version,policy_hash) VALUES (?,?,?,?,?,\'{}\',\'[]\',UTC_TIMESTAMP(),?,?)',[$a['customer_id'],$a['id'],$v['id'],$package['id'],$p['id'],$policy['version'],$policy['hash']]);$id=(int)db()->lastInsertId();cat_event($a,cat_request($a,$id),'draft_created');return ['ok'=>true,'id'=>$id];});
}
function cat_save(array $a,int $id,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Ответы сохраняет клиент.');return crm_idempotent('catalog:save:'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$r=cat_request($a,$id,true);crm_version($d,$r);if($r['state']!=='DRAFT')crm_fail(409,'Редактировать можно только черновик.');cc_project($a,(int)$r['project_id'],true,true);$policy=cat_consent($d);$live=cat_live((int)$r['service_version_id']);$answers=cat_answers($live['template']['data'],$d['answers']??null,false);$ids=$d['file_ids']??[];cat_files($a,(int)$r['project_id'],$ids);crm_query('UPDATE nd_catalog_requests SET answers_json=?,file_ids_json=?,consent_at=UTC_TIMESTAMP(),policy_version=?,policy_hash=?,version=version+1 WHERE id=?',[ai_json((object)$answers),ai_json($ids),$policy['version'],$policy['hash'],$id]);return ['ok'=>true,'id'=>$id];});
}
function cat_structured(array $r,array $live,array $answers,array $files):array{
 $v=$live['version']['data'];$package=cat_package($live['version'],$r['package_key']);$groups=array_fill_keys(['goal','functionality','integrations','design','deliverables','budget','deadline','other'],[]);$missing=[];
 foreach($live['template']['data']['steps'] as $step)foreach($step['questions'] as $q){if(!cat_visible($q,$answers))continue;if(!array_key_exists($q['id'],$answers)){$missing[]=$q['label'];continue;}$answer=$answers[$q['id']];$groups[$q['semantic']][]=['question'=>$q['label'],'answer'=>$answer];}
 return ['request_id'=>(int)$r['id'],'service_version_id'=>(int)$r['service_version_id'],'service'=>$v['name'],'category'=>$v['category'],'package'=>['id'=>$package['id'],'name'=>$package['name'],'description'=>$package['description']],'answers'=>(object)$answers,'sections'=>$groups,'service_scope'=>$v['scope'],'service_deliverables'=>$v['deliverables'],'attachments'=>$files,'missing_information'=>$missing,'assumptions'=>[],'meaning'=>'Ответы клиента сохранены буквально. Бюджет/желаемый срок — ограничения, не коммерческие обещания.'];
}
function cat_brief_text(array $brief):string{$lines=['Услуга: '.$brief['service'],'Пакет: '.$brief['package']['name']];foreach($brief['sections'] as $rows)foreach($rows as $x)$lines[]=$x['question'].': '.(is_array($x['answer'])?implode(', ',$x['answer']):(is_bool($x['answer'])?($x['answer']?'Да':'Нет'):(string)$x['answer']));$text=implode("\n",$lines);if(mb_strlen($text)>8500)crm_fail(422,'Сократите ответы: полный бриф должен укладываться в 8500 символов.');return $text;}
function cat_submit(array $a,int $id,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Бриф отправляет клиент.');return crm_idempotent('catalog:submit:'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$r=cat_request($a,$id,true);if($r['state']==='SUBMITTED'||$r['state']==='PRICING')return ['ok'=>true,'id'=>$id];crm_version($d,$r);if($r['state']!=='DRAFT')crm_fail(409,'Бриф уже отправлен или закрыт.');$policy=cat_consent($d);$live=cat_live((int)$r['service_version_id']);$answers=cat_answers($live['template']['data'],json_decode($r['answers_json'],true),true);$files=cat_files($a,(int)$r['project_id'],json_decode($r['file_ids_json'],true));$brief=cat_structured($r,$live,$answers,$files);$raw=ai_json($brief);$text=cat_brief_text($brief);$p=cc_project($a,(int)$r['project_id'],true,true);$owner=['type'=>'owner','id'=>1];
 crm_query('UPDATE nd_projects SET description=?,version=version+1 WHERE id=?',[$text,$p['id']]);
 if(!$r['lead_id']){$account=ca_account((int)$a['id'],true);if(!ca_account_allowed($account)||!ca_current_consent($account))crm_fail(401,'Подтвердите актуальные документы в кабинете.');$customer=crm_record('customers',(int)$r['customer_id']);$key=hash('sha256','catalog-lead:'.$id);crm_query("INSERT INTO nd_leads(name,contact,service,idea,notes,created,request_key,request_hash,consent,consent_at,policy_version,policy_hash) VALUES (?,?,?,?,?,UNIX_TIMESTAMP(),?,?,1,UNIX_TIMESTAMP(),?,?)",[mb_substr($customer['name'],0,100),$account['email'],mb_substr($brief['service'],0,100),$text,'Бриф каталога №'.$id,$key,hash('sha256',$raw),$policy['version'],$policy['hash']]);$lead=(int)db()->lastInsertId();crm_query('INSERT INTO nd_lead_customers(lead_id,customer_id) VALUES (?,?)',[$lead,$r['customer_id']]);$deal=crm_insert('deals',['title'=>mb_substr($brief['service'],0,190),'customer_id'=>(int)$r['customer_id'],'lead_id'=>$lead,'currency'=>'RUB'],$a)['record'];crm_query('UPDATE nd_catalog_requests SET lead_id=?,deal_id=? WHERE id=?',[$lead,$deal['id'],$id]);}
 $doc=cc_create_document_effect($owner,(int)$p['id'],['kind'=>'specification','title'=>'ТЗ по брифу №'.$id,'fields'=>['title'=>'ТЗ по брифу №'.$id,'requirements'=>$text,'acceptance'=>implode("\n",$brief['service_deliverables']),'constraints'=>'Желаемые бюджет и срок из брифа не являются обещанием. Условия утверждаются в предложении.'],'file_ids'=>json_decode($r['file_ids_json'],true)]);$n=(int)$r['head_revision']+1;crm_query('INSERT INTO nd_catalog_briefs(request_id,revision_number,answers_json,structured_json,checksum,spec_revision_id,consent_at,policy_version,policy_hash) VALUES (?,?,?,?,?,?,UTC_TIMESTAMP(),?,?)',[$id,$n,$r['answers_json'],$raw,hash('sha256',$raw),$doc['id'],$policy['version'],$policy['hash']]);crm_query("UPDATE nd_catalog_requests SET head_revision=?,state='SUBMITTED',version=version+1 WHERE id=?",[$n,$id]);cat_event($a,$r,'submitted');return ['ok'=>true,'id'=>$id];});
}
function cat_estimate(int $id,array $d):array{
 return crm_idempotent('catalog:estimate:'.$id,$d,function()use($id,$d){$a=['type'=>'owner','id'=>1];$r=cat_request($a,$id,true);if(!in_array($r['state'],['SUBMITTED','PRICING'],true))crm_fail(409,'Оценивать можно только отправленный бриф.');$b=cat_brief($r);$v=cat_version('service',(int)$r['service_version_id']);$package=cat_package($v,$r['package_key']);$work=$package['work_packages'];$answers=json_decode($b['answers_json'],true);
 foreach($package['quantity_rules'] as $rule){$value=$answers[$rule['question']]??null;$work[$rule['package_index']][$rule['quantity']]=is_int($value)?(string)$value:null;}foreach(['owner_review_hours'=>'Проверка результата владельцем','correction_hours'=>'Исправления владельцем'] as $field=>$label)$work[]=['name'=>$label,'development_hours'=>$package[$field],'testing_hours'=>'0','ai_input_tokens'=>'0','ai_output_tokens'=>'0','hosting_months'=>'0','tool_units'=>'0','external_units'=>'0','other_units'=>'0','risk'=>'medium','uncertain'=>true,'basis'=>'Явная оценочная модель владельца для данной редакции услуги; null означает неизвестное.'];$e=pricing_estimate((int)$r['project_id'],$work,null,'owner');$q=pricing_quote($e,$v['data']['pricing_type']==='fixed'?$package['price']:null);crm_query("UPDATE nd_catalog_requests SET state='PRICING',version=version+1 WHERE id=?",[$id]);cat_event($a,$r,'estimated');return ['ok'=>true,'id'=>$id,'quotation_id'=>(int)$q['id'],'pricing_status'=>$q['state'],'basis'=>'Конфигурируемая владельцем оценочная модель пакета; неизвестные значения сохранены.'];});
}
function cat_auto_estimate(int $id):array{
 try{$r=cat_request(['type'=>'owner','id'=>1],$id);$b=cat_brief($r);$d=['request_key'=>hash('sha256','catalog-estimate:'.$b['checksum'])];$out=cat_estimate($id,$d);}
 catch(Throwable $e){if(!($e instanceof CrmFailure))error_log('NeuroDelo '.ai_json(['event'=>'catalog_estimation_unavailable','type'=>get_class($e),'file'=>basename($e->getFile()),'line'=>$e->getLine()]));$out=['ok'=>true,'id'=>$id,'pricing_status'=>'NEEDS_COST_REVIEW','estimation_available'=>false];}
 if((config()['ai_enabled']??false)===true&&(config()['ai_pricing_auto_enabled']??false)===true&&(config()['ai_data_processing_approved']??false)===true){try{$r=cat_request(['type'=>'owner','id'=>1],$id);$b=cat_brief($r);$t=ai_create(['type'=>'owner','id'=>'1'],['agent'=>'cost_estimator','project_id'=>(int)$r['project_id'],'question'=>'Оцените все работы по брифу, включая время проверки владельцем, тесты, исправления и внешние расходы. Неизвестные количества null, не ноль. Не утверждайте цену.','request_key'=>hash('sha256','catalog-ai-estimate:'.$b['checksum'])]);$out['ai_task_id']=$t['id'];}catch(Throwable $e){if(!($e instanceof CrmFailure))error_log('NeuroDelo '.ai_json(['event'=>'catalog_ai_queue_unavailable','type'=>get_class($e),'file'=>basename($e->getFile()),'line'=>$e->getLine()]));$out['ai_available']=false;}}
 return $out;
}
